// Browser port of Chatbot/chat.py: same weights, same bag-of-words input.
// finder-model.json is generated by scripts/export_finder.py.

const vowelAt = (w, i) => 'aeiou'.includes(w[i]) || (w[i] === 'y' && i > 0 && !vowelAt(w, i - 1));
const hasVowel = (s) => [...s].some((_, i) => vowelAt(s, i));
const measure = (s) => [...s].map((_, i) => (vowelAt(s, i) ? 'v' : 'c')).join('').replace(/(.)\1*/g, '$1').split('vc').length - 1;
const doubled = (s) => s.length > 1 && s.at(-1) === s.at(-2) && !vowelAt(s, s.length - 1);
const cvc = (s) => {
  const n = s.length;
  if (n >= 3) return !vowelAt(s, n - 3) && vowelAt(s, n - 2) && !vowelAt(s, n - 1) && !'wxy'.includes(s[n - 1]);
  return n === 2 && vowelAt(s, 0) && !vowelAt(s, 1);
};

// [suffix, replacement, condition]; the first matching suffix decides.
function rules(w, list) {
  for (const [suf, rep, cond] of list) {
    if (w.endsWith(suf)) {
      const s = w.slice(0, w.length - suf.length);
      return !cond || cond(s) ? s + rep : w;
    }
  }
  return w;
}

const m0 = (s) => measure(s) > 0;
const m1 = (s) => measure(s) > 1;
const each = (cond, pairs) => pairs.split(' ').map((p) => [...p.split(':'), cond]);

const STEP2 = [
  ...each(m0, 'ational:ate tional:tion enci:ence anci:ance izer:ize bli:ble alli:al entli:ent eli:e ousli:ous ization:ize ation:ate ator:ate alism:al iveness:ive fulness:ful ousness:ous aliti:al iviti:ive biliti:ble fulli:ful'),
  ['logi', 'log', (s) => m0(s + 'l')],
];
const STEP3 = each(m0, 'icate:ic ative: alize:al iciti:ic ical:ic ful: ness:');
const STEP4 = [
  ...each(m1, 'al: ance: ence: er: ic: able: ible: ant: ement: ment: ent:'),
  ['ion', '', (s) => m1(s) && /[st]$/.test(s)],
  ...each(m1, 'ou: ism: ate: iti: ous: ive: ize:'),
];

// Porter stemmer with NLTK's extensions, which is what the model was trained on.
export function stem(word) {
  let w = word.toLowerCase();
  if (w.length <= 2) return w;

  if (w.endsWith('ies') && w.length === 4) w = w.slice(0, -1);
  else w = rules(w, [['sses', 'ss'], ['ies', 'i'], ['ss', 'ss'], ['s', '']]);

  if (w.endsWith('ied')) w = w.slice(0, -3) + (w.length === 4 ? 'ie' : 'i');
  else if (w.endsWith('eed')) {
    if (m0(w.slice(0, -3))) w = w.slice(0, -1);
  } else {
    const suf = ['ed', 'ing'].find((x) => w.endsWith(x) && hasVowel(w.slice(0, -x.length)));
    if (suf) {
      const s = w.slice(0, -suf.length);
      if (/(at|bl|iz)$/.test(s)) w = s + 'e';
      else if (doubled(s)) w = 'lsz'.includes(s.at(-1)) ? s : s.slice(0, -1);
      else w = measure(s) === 1 && cvc(s) ? s + 'e' : s;
    }
  }

  if (w.endsWith('y') && w.length > 2 && !vowelAt(w, w.length - 2)) w = w.slice(0, -1) + 'i';
  if (w.endsWith('alli') && m0(w.slice(0, -4))) w = w.slice(0, -2);
  w = rules(w, STEP2);
  w = rules(w, STEP3);
  w = rules(w, STEP4);

  if (w.endsWith('e')) {
    const s = w.slice(0, -1);
    if (m1(s) || (measure(s) === 1 && !cvc(s))) w = s;
  }
  if (w.endsWith('ll') && m1(w.slice(0, -1))) w = w.slice(0, -1);
  return w;
}

export function tokenize(text) {
  return text
    .replace(/’/g, "'")
    .replace(/n't\b/gi, " n't")
    .replace(/'(s|m|re|ve|ll|d)\b/gi, " '$1")
    .match(/n't|'(?:s|m|re|ve|ll|d)\b|[\w-]+/gi) ?? [];
}

export function predict(model, sentence) {
  const seen = new Set(tokenize(sentence).map(stem));
  let x = model.words.map((w) => (seen.has(w) ? 1 : 0));
  const known = x.some(Boolean);
  model.layers.forEach(([weight, bias], i) => {
    const input = x;
    x = weight.map((row, j) => row.reduce((s, v, k) => s + v * input[k], bias[j]));
    if (i < model.layers.length - 1) x = x.map((v) => Math.max(0, v));
  });
  const top = Math.max(...x);
  const e = x.map((v) => Math.exp(v - top));
  const sum = e.reduce((a, b) => a + b);
  const best = x.indexOf(top);
  return { tag: model.tags[best], prob: e[best] / sum, known };
}
